import { BuildOptions, Page } from './types';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  pages: Page[];
  [key: string]: unknown;
}

export interface Plugin {
  name?: string;
  onStart?(context: PluginContext): void | Promise<void>;
  beforeBuild?(context: PluginContext): void | Promise<void>;
  afterBuild?(context: PluginContext): void | Promise<void>;
  onFile?(page: Page, context: PluginContext): Page | void | Promise<Page | void>;
  onEnd?(context: PluginContext): void | Promise<void>;
}

export function createContext(options: BuildOptions): PluginContext {
  return {
    contentDir: options.contentDir,
    outputDir: options.outputDir,
    templatesDir: options.templatesDir ?? './templates',
    pages: [],
  };
}

export class PluginPipeline {
  private readonly plugins: Plugin[];

  constructor(plugins: Plugin[]) {
    this.plugins = [...plugins];
  }

  getPlugins(): Plugin[] {
    return [...this.plugins];
  }

  runOnStart(context: PluginContext): void {
    for (const plugin of this.plugins) {
      plugin.onStart?.(context);
    }
  }

  runBeforeBuild(context: PluginContext): void {
    for (const plugin of this.plugins) {
      plugin.beforeBuild?.(context);
    }
  }

  runOnFile(page: Page, context: PluginContext): Page {
    let current = page;
    for (const plugin of this.plugins) {
      const result = plugin.onFile?.(current, context);
      if (result !== undefined) current = result;
    }
    return current;
  }

  runAfterBuild(context: PluginContext): void {
    for (const plugin of this.plugins) {
      plugin.afterBuild?.(context);
    }
  }

  runOnEnd(context: PluginContext): void {
    for (const plugin of this.plugins) {
      plugin.onEnd?.(context);
    }
  }

  async runOnStartAsync(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onStart?.(context);
    }
  }

  async runBeforeBuildAsync(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.beforeBuild?.(context);
    }
  }

  async runOnFileAsync(page: Page, context: PluginContext): Promise<Page> {
    let current = page;
    for (const plugin of this.plugins) {
      const result = await plugin.onFile?.(current, context);
      if (result !== undefined) current = result;
    }
    return current;
  }

  async runAfterBuildAsync(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.afterBuild?.(context);
    }
  }

  async runOnEndAsync(context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onEnd?.(context);
    }
  }
}

import { Plugin, PluginContext } from '../plugin';
import { Page } from '../types';
import { loadPages } from '../markdown';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: PluginContext): void {
    context.pages = loadPages(context.contentDir);
  }

  onFile(page: Page, _context: PluginContext): Page {
    return page;
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext } from '../plugin';
import { Page } from '../types';
import { TemplateEngine } from '../templates';

export class TemplatePlugin implements Plugin {
  name = 'templates';

  private engine: TemplateEngine | null = null;

  beforeBuild(context: PluginContext): void {
    this.engine = new TemplateEngine(context.templatesDir);
  }

  onFile(page: Page, context: PluginContext): Page {
    const html = this.requireEngine().renderPage(page, context.pages);
    fs.writeFileSync(path.join(context.outputDir, `${page.slug}.html`), html, 'utf-8');
    return page;
  }

  afterBuild(context: PluginContext): void {
    const indexHtml = this.requireEngine().renderIndex(context.pages);
    fs.writeFileSync(path.join(context.outputDir, 'index.html'), indexHtml, 'utf-8');
  }

  private requireEngine(): TemplateEngine {
    if (!this.engine) {
      throw new Error('TemplatePlugin has not been initialized');
    }
    return this.engine;
  }
}

import { Plugin, PluginContext } from '../plugin';
import { DevServer, DevServerOptions } from '../server';

export class DevServerPlugin implements Plugin {
  name = 'dev-server';

  private server: DevServer | null = null;
  private readonly options?: DevServerOptions;

  constructor(options?: DevServerOptions) {
    this.options = options;
  }

  onStart(context: PluginContext): void {
    const options: DevServerOptions = this.options ?? {
      contentDir: context.contentDir,
      outputDir: context.outputDir,
      templatesDir: context.templatesDir,
      port: typeof context.port === 'number' ? context.port : 3000,
      host: typeof context.host === 'string' ? context.host : undefined,
    };
    this.server = new DevServer(options);
    void this.server.start().catch((err) => {
      console.error(err instanceof Error ? err.message : String(err));
    });
  }

  onEnd(_context: PluginContext): void {
    void this.server?.stop();
    this.server = null;
  }

  getServer(): DevServer | null {
    return this.server;
  }
}

export { MarkdownPlugin } from './markdown';
export { TemplatePlugin } from './templates';
export { DevServerPlugin } from './dev-server';

import fs from 'fs';
import { BuildOptions, Page } from './types';
import { Plugin, PluginContext, PluginPipeline, createContext } from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/templates';

export function createDefaultPlugins(userPlugins: Plugin[] = []): Plugin[] {
  return [new MarkdownPlugin(), ...userPlugins, new TemplatePlugin()];
}

export class SSGEngine {
  private readonly pipeline: PluginPipeline;

  constructor(plugins: Plugin[]) {
    this.pipeline = new PluginPipeline(plugins);
  }

  getPlugins(): Plugin[] {
    return this.pipeline.getPlugins();
  }

  build(options: BuildOptions): Page[] {
    const context = createContext(options);

    this.pipeline.runOnStart(context);
    this.pipeline.runBeforeBuild(context);

    fs.mkdirSync(context.outputDir, { recursive: true });

    const pages = context.pages;
    for (let i = 0; i < pages.length; i++) {
      const transformed = this.pipeline.runOnFile(pages[i], context);
      if (transformed !== undefined) {
        pages[i] = transformed;
      }
    }

    this.pipeline.runAfterBuild(context);
    this.pipeline.runOnEnd(context);

    return context.pages;
  }

  async buildAsync(options: BuildOptions): Promise<Page[]> {
    const context = createContext(options);

    await this.pipeline.runOnStartAsync(context);
    await this.pipeline.runBeforeBuildAsync(context);

    await fs.promises.mkdir(context.outputDir, { recursive: true });

    const pages = context.pages;
    for (let i = 0; i < pages.length; i++) {
      const transformed = await this.pipeline.runOnFileAsync(pages[i], context);
      if (transformed !== undefined) {
        pages[i] = transformed;
      }
    }

    await this.pipeline.runAfterBuildAsync(context);
    await this.pipeline.runOnEndAsync(context);

    return context.pages;
  }
}

export function createEngine(userPlugins: Plugin[] = []): SSGEngine {
  return new SSGEngine(createDefaultPlugins(userPlugins));
}

import fs from 'fs';
import path from 'path';
import Module from 'module';
import ts from 'typescript';
import { Plugin } from './plugin';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/templates';
import { DevServerPlugin } from './plugins/dev-server';

export interface SsgConfig {
  plugins?: Array<string | Plugin>;
  contentDir?: string;
  outputDir?: string;
  templatesDir?: string;
  port?: number;
  host?: string;
}

export const CONFIG_FILENAMES = ['ssg.config.ts', 'ssg.config.js', 'ssg.config.json'];

const BUILTIN_PLUGIN_FACTORIES: Record<string, new () => Plugin> = {
  markdown: MarkdownPlugin,
  templates: TemplatePlugin,
  'dev-server': DevServerPlugin,
};

let tsRequireHookInstalled = false;

function installTsRequireHook(): void {
  if (tsRequireHookInstalled) return;
  tsRequireHookInstalled = true;

  const extensions = (Module as unknown as { _extensions: Record<string, unknown> })._extensions;
  const compile: (module: NodeModule, filename: string) => void = (module, filename) => {
    const source = fs.readFileSync(filename, 'utf-8');
    const compiled = ts.transpileModule(source, {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
      },
    }).outputText;
    (module as unknown as { _compile: (code: string, filename: string) => void })._compile(
      compiled,
      filename
    );
  };
  extensions['.ts'] = compile;
  extensions['.tsx'] = compile;
}

function requireModule(file: string): unknown {
  installTsRequireHook();
  const req = Module.createRequire(file);
  return req(file);
}

function defaultExport(value: unknown): unknown {
  if (value && typeof value === 'object' && 'default' in (value as Record<string, unknown>)) {
    return (value as Record<string, unknown>).default;
  }
  return value;
}

function requireConfig(file: string): unknown {
  if (file.endsWith('.json')) {
    return JSON.parse(fs.readFileSync(file, 'utf-8'));
  }
  return defaultExport(requireModule(file));
}

export function findConfigFile(baseDir: string = process.cwd()): string | null {
  for (const name of CONFIG_FILENAMES) {
    const candidate = path.join(baseDir, name);
    if (fs.existsSync(candidate)) return candidate;
  }
  return null;
}

export function loadConfig(configPath?: string): SsgConfig {
  const file = configPath ?? findConfigFile();
  if (!file) return {};
  const config = requireConfig(file);
  if (config == null) return {};
  if (typeof config !== 'object') {
    throw new Error(`Invalid SSG config: expected an object in ${file}`);
  }
  return config as SsgConfig;
}

function resolvePluginFile(spec: string, baseDir: string): string | null {
  const candidates = [
    path.resolve(baseDir, spec),
    path.resolve(baseDir, 'plugins', spec),
    path.resolve(baseDir, spec, 'index'),
  ];
  const extensions = ['', '.ts', '.js'];
  for (const candidate of candidates) {
    for (const ext of extensions) {
      const file = candidate + ext;
      if (fs.existsSync(file)) return file;
    }
  }
  return null;
}

function instantiatePlugin(value: unknown): Plugin {
  if (typeof value === 'function') {
    return new (value as new () => Plugin)();
  }
  if (value && typeof value === 'object') {
    return value as Plugin;
  }
  throw new Error(`Plugin module must export a Plugin object or constructor`);
}

export function resolvePlugin(spec: string | Plugin, baseDir: string = process.cwd()): Plugin {
  if (typeof spec === 'object' && spec !== null) {
    return spec;
  }
  if (typeof spec !== 'string') {
    throw new Error(`Invalid plugin: ${String(spec)}`);
  }

  const factory = BUILTIN_PLUGIN_FACTORIES[spec];
  if (factory) return new factory();

  const file = resolvePluginFile(spec, baseDir);
  if (!file) {
    throw new Error(`Plugin not found: ${spec}`);
  }
  return instantiatePlugin(defaultExport(requireModule(file)));
}

export function loadPlugins(config?: SsgConfig, baseDir: string = process.cwd()): Plugin[] {
  const specs = config?.plugins ?? [];
  return specs.map((spec) => resolvePlugin(spec, baseDir));
}

export function createConfiguredPlugins(
  config?: SsgConfig,
  baseDir: string = process.cwd()
): Plugin[] {
  return createConfiguredPipeline(config, baseDir);
}

export function createConfiguredPipeline(
  config?: SsgConfig,
  baseDir: string = process.cwd()
): Plugin[] {
  const userPlugins = loadPlugins(config, baseDir);
  return [new MarkdownPlugin(), ...userPlugins, new TemplatePlugin()];
}

import { BuildOptions, Page } from './types';
import { Plugin } from './plugin';
import { createEngine } from './engine';

export function build(options: BuildOptions, plugins: Plugin[] = []): Page[] {
  return createEngine(plugins).build(options);
}

