function tmp(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

describe('plugin system self-check', () => {
  it('runs pipeline hooks in order', () => {
    const order: string[] = [];
    const a: Plugin = {
      name: 'a',
      onStart: () => order.push('a:onStart'),
      beforeBuild: () => order.push('a:beforeBuild'),
      onFile: () => order.push('a:onFile'),
      afterBuild: () => order.push('a:afterBuild'),
      onEnd: () => order.push('a:onEnd'),
    };
    const b: Plugin = {
      name: 'b',
      onStart: () => order.push('b:onStart'),
      beforeBuild: () => order.push('b:beforeBuild'),
      onFile: () => order.push('b:onFile'),
      afterBuild: () => order.push('b:afterBuild'),
      onEnd: () => order.push('b:onEnd'),
    };
    const content = tmp('pgc-');
    const out = tmp('pgo-');
    fs.writeFileSync(path.join(content, 'x.md'), '---\ntitle: X\n---\n# X\n');
    createEngine([a, b]).build({ contentDir: content, outputDir: out });
    expect(order).toEqual([
      'a:onStart', 'b:onStart',
      'a:beforeBuild', 'b:beforeBuild',
      'a:onFile', 'b:onFile',
      'a:afterBuild', 'b:afterBuild',
      'a:onEnd', 'b:onEnd',
    ]);
    fs.rmSync(content, { recursive: true, force: true });
    fs.rmSync(out, { recursive: true, force: true });
  });

  it('loads plugins from ssg.config.ts', () => {
    const dir = tmp('cfg-');
    const pluginsDir = path.join(dir, 'plugins');
    fs.mkdirSync(pluginsDir, { recursive: true });
    fs.writeFileSync(
      path.join(pluginsDir, 'shout.ts'),
      "import { Plugin } from '../../src/plugin';\n" +
        "const plugin: Plugin = { name: 'shout', onFile: (page: any) => ({ ...page, title: page.title.toUpperCase() }) };\n" +
        'export default plugin;\n'
    );
    fs.writeFileSync(
      path.join(dir, 'ssg.config.ts'),
      "export default { plugins: ['./plugins/shout'] };\n"
    );
    const config = loadConfig(path.join(dir, 'ssg.config.ts'));
    expect(config.plugins).toEqual(['./plugins/shout']);
    const plugins = loadPlugins(config, dir);
    expect(plugins.length).toBe(1);
    expect(plugins[0].name).toBe('shout');
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it('user plugin onFile transforms title before template writes file', () => {
    const content = tmp('upc-');
    const out = tmp('upo-');
    fs.writeFileSync(path.join(content, 'x.md'), '---\ntitle: hello\n---\n# Hi\n');
    const shout: Plugin = {
      name: 'shout',
      onFile: (page: Page) => ({ ...page, title: page.title.toUpperCase() }),
    };
    build({ contentDir: content, outputDir: out }, [shout]);
    const html = fs.readFileSync(path.join(out, 'x.html'), 'utf-8');
    expect(html).toContain('<h1>HELLO</h1>');
    fs.rmSync(content, { recursive: true, force: true });
    fs.rmSync(out, { recursive: true, force: true });
  });
});

